package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.Perfil;import jakarta.persistence.*;@Entity@Table(name="usuarios",uniqueConstraints=@UniqueConstraint(columnNames={"restaurante_id","email"}))public class Usuario extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;@Column(nullable=false)private String nome;@Column(nullable=false)private String email;@Column(nullable=false)private String senhaHash;@Enumerated(EnumType.STRING)private Perfil perfil;private boolean ativo=true;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public String getNome(){return nome;}public void setNome(String v){nome=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getSenhaHash(){return senhaHash;}public void setSenhaHash(String v){senhaHash=v;}public Perfil getPerfil(){return perfil;}public void setPerfil(Perfil v){perfil=v;}public boolean isAtivo(){return ativo;}public void setAtivo(boolean v){ativo=v;}}
